def solve_sequence(x1, x2):
    """Generates the sequence and returns its length."""
    sequence = [x1, x2]

    while True:
        # x_i is the last term, x_{i-1} is the second to last term
        xi = sequence[-1]
        xi_minus_1 = sequence[-2]

        # Calculate x_{i+1} using the recurrence: x_{i+1} = (x_i^2 - x_{i-1}) / (x_{i-1} + 1)
        numerator = xi * xi - xi_minus_1
        denominator = xi_minus_1 + 1

        if denominator == 0:
            # Should not happen given x_i-1 >= 1
            return len(sequence)

        if numerator % denominator != 0:
            # Not an integer
            return len(sequence)

        x_next = numerator // denominator

        if x_next <= 0:
            # Not a positive integer
            return len(sequence)

        sequence.append(x_next)

        # Safety break for extremely long sequences (though 100x100 is usually finite)
        if len(sequence) > 100: 
             return len(sequence)

    return len(sequence)

def find_longest_sequence(limit=100):
    max_n = 0
    best_sequence = []
    best_pair = None

    print(f"Starting systematic search for x1, x2 up to {limit}...")

    for x1 in range(1, limit + 1):
        for x2 in range(1, limit + 1):
            n = solve_sequence(x1, x2)

            if n > max_n:
                max_n = n
                # Recalculate the actual sequence for logging purposes
                current_sequence = [x1, x2]
                xi, xi_minus_1 = x2, x1
                for _ in range(n - 2):
                    numerator = xi * xi - xi_minus_1
                    denominator = xi_minus_1 + 1
                    x_next = numerator // denominator
                    current_sequence.append(x_next)
                    xi_minus_1 = xi
                    xi = x_next

                best_sequence = current_sequence
                best_pair = (x1, x2)

            # Optimization: If we found a very long sequence already, we might stop early, 
            # but since the search space is manageable (10000 iterations), we run it fully.

    return max_n, best_pair, best_sequence

MAX_LIMIT = 100
max_n, best_pair, best_sequence = find_longest_sequence(MAX_LIMIT)

print(f"Search Complete.")
print(f"Maximum length (n): {max_n}")
if best_pair:
    print(f"Best starting pair (x1, x2): {best_pair}")
    print(f"Sequence found: {best_sequence}")
else:
    print("No sequence found (should not happen if limit >= 2)")

